// [start, end) intervals: back-to-back bookings do not overlap
export const overlaps = (a, b) => a.startAt < b.endAt && b.startAt < a.endAt;

export function isFree(existing, wanted) {
  return !existing.some((b) => overlaps(b, wanted));
}

