export const FREQS = ['daily', 'weekly'];

export function makeRule({ freq, interval = 1, until }) {
  if (!FREQS.includes(freq)) throw new Error(`unsupported frequency ${freq}`);
  return { freq, interval, until };
}

files.src/recurrence/expand.js:
const MAX = 52;
const DAY = 86400000;

export function expand(first, rule) {
  const step = (rule.freq === 'weekly' ? 7 : 1) * rule.interval * DAY;
  const out = [];
  for (let t = Date.parse(first); out.length < MAX && (!rule.until || t <= Date.parse(rule.until)); t += step) out.push(new Date(t));
  return out;
}

