export function toUtc(localIso, zone) {
  const asUtc = new Date(localIso + 'Z');
  const inZone = new Date(asUtc.toLocaleString('en-US', { timeZone: zone }));
  const offset = inZone.getTime() - new Date(asUtc.toLocaleString('en-US', { timeZone: 'UTC' })).getTime();
  return new Date(asUtc.getTime() - offset).toISOString();
}

