import { roomsOfSite } from '../rooms/catalog.js';
import { listForRoom } from '../store/bookings-pg.js';
import { isFree } from './single.js';

export async function freeRoomsAtSite(siteId, slot) {
  const rooms = roomsOfSite(siteId);
  const checks = await Promise.all(rooms.map(async (r) => isFree(await listForRoom(r.id), slot)));
  return rooms.filter((_, i) => checks[i]);
}

