import { send } from '../mail/provider.js';
import { reminderAt } from './schedule.js';

export async function sendDue(bookings, now = new Date()) {
  const due = bookings.filter((b) => !b.cancelledAt && !b.remindedAt && reminderAt(b) <= now.toISOString());
  for (const b of due) await send({ to: b.memberEmail, subject: 'Your meeting starts soon', html: `Room ${b.roomId}` });
  return due.map((b) => b.id);
}

